css:
.highlight-box {
    background-color: var(--white);
    border-left: 5px solid var(--green-dark);
    border-radius: 6px; padding: 15px; margin: 15px 0;
    font-family: 'Inter', sans-serif;
    color: var(--green-dark);
    box-shadow: 0 1px 4px rgba(0,0,0,0.06);
}
.highlight-box .mjx-container { color: var(--green-dark); }
.highlight-box p { color: var(--brown-dark); }
.idea-box {
    background-color: #E8F5E9;
    border-left: 5px solid var(--green-light);
    border-radius: 6px; padding: 15px; margin: 15px 0;
}
.warning-box {
    background-color: #FFEBEE;
    border-left: 5px solid #E57373;
    border-radius: 6px; padding: 15px; margin: 15px 0;
}
/* ─── Formula Tiles ─── */
.formula-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; margin: 16px 0; }
.formula-tile {
    background: var(--white); border: 2px solid var(--green-dark);
    border-radius: 10px; padding: 18px 16px;
    box-shadow: 0 1px 4px rgba(0,0,0,0.06);
}
.formula-tile h4 {
    font-family: 'Switzer', 'Space Grotesk', sans-serif;
    color: var(--brown-dark); font-size: 14px; margin-bottom: 8px;
}
.formula-tile .mjx-container { color: var(--green-dark); }
.formula-tile .formula-note {
    font-size: 12.5px; color: var(--brown-medium);
    margin-top: 6px; line-height: 1.5;
}
.example-body .highlight-box, .solution-body .highlight-box { margin: 8px 0; }
.formula-grid { grid-template-columns: 1fr; }
.ext-link { color: #21442B; font-weight: 600; text-decoration: underline; text-underline-offset: 3px; }
.ext-link:hover { color: #BC6C26; }
.fmt-grid { grid-template-columns: repeat(3, 1fr); }
.fmt-tile { text-align: center; }
.fmt-tile h4 { font-size: 16px; margin-bottom: 8px; }
.fmt-tile .formula-note { font-size: 14px; line-height: 1.5; }
.btn-mini { margin-left: 8px; padding: 4px 10px; font-size: 12px; font-family: inherit; border: 1.5px solid var(--green-dark); background: white; color: var(--green-dark); border-radius: 8px; cursor: pointer; font-weight: 600; }
.btn-mini:hover { background: var(--green-dark); color: white; }
.sp-stage { margin-top: 14px; border: 1.5px solid var(--cream-dark); border-radius: 12px; padding: 16px; background: #fafafa; }
.sp-hud { display: flex; gap: 16px; font-size: 13px; color: var(--text-medium); margin-bottom: 12px; flex-wrap: wrap; }
.sp-hud b { color: var(--green-dark); }
.fs-item { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin-bottom: 12px; }
.fs-box { background: white; border: 1.5px solid var(--cream-dark); border-radius: 10px; padding: 12px 14px; }
.fs-box .fs-lab { font-size: 11px; font-weight: 700; letter-spacing: 0.6px; text-transform: uppercase; color: var(--text-medium); margin-bottom: 6px; }
.fs-box .fs-val { font-size: 22px; font-weight: 700; color: var(--brown-dark); font-family: 'Inter', sans-serif; }
.fs-box.typed .fs-val { font-family: 'Courier New', monospace; background: #fff; border: 2px solid var(--green-dark); border-radius: 6px; padding: 4px 10px; display: inline-block; min-width: 90px; }
.sp-actions { display: flex; gap: 10px; flex-wrap: wrap; }
.sp-actions button { font-family: inherit; font-weight: 700; font-size: 14px; padding: 10px 18px; border-radius: 10px; border: 2px solid var(--green-dark); background: white; color: var(--green-dark); cursor: pointer; }
.sp-actions button:hover { background: var(--green-dark); color: white; }
.sp-actions button.no { border-color: #B23A3A; color: #B23A3A; }
.sp-actions button.no:hover { background: #B23A3A; color: white; }
.sp-verdict { margin-top: 12px; font-size: 14px; min-height: 22px; }
.sp-verdict.ok { color: var(--green-dark); font-weight: 600; }
.sp-verdict.bad { color: #B23A3A; font-weight: 600; }
.sp-verdict .rule { display: inline-block; font-size: 11px; font-weight: 700; letter-spacing: 0.5px; text-transform: uppercase; background: rgba(33,68,43,0.10); color: var(--green-dark); padding: 2px 8px; border-radius: 8px; margin-right: 6px; }
.sp-verdict .why { color: var(--text-dark); font-weight: 400; }
.sp-done { font-size: 18px; font-weight: 700; color: var(--green-dark); }
.sp-done small { display: block; font-size: 13px; font-weight: 400; color: var(--text-medium); margin-top: 4px; }
.fp-list { display: flex; flex-direction: column; gap: 12px; margin-top: 14px; }
.fp-item { border: 1.5px solid var(--cream-dark); border-radius: 12px; padding: 14px 16px; background: #fafafa; }
.fp-item.done { border-color: var(--green-dark); background: rgba(33,68,43,0.05); }
.fp-q { font-size: 15px; color: var(--text-dark); margin-bottom: 10px; }
.fp-q .n { display: inline-block; width: 24px; height: 24px; line-height: 24px; text-align: center; border-radius: 50%; background: var(--gold); color: white; font-weight: 700; font-size: 12px; margin-right: 8px; }
.fp-row { display: flex; gap: 10px; align-items: center; flex-wrap: wrap; }
.fp-input { font-family: 'Courier New', monospace; font-size: 20px; font-weight: 700; width: 150px; padding: 8px 10px; border: 2px solid var(--green-dark); border-radius: 8px; color: var(--brown-dark); background: white; }
.fp-input:focus { outline: none; box-shadow: 0 0 0 3px rgba(33,68,43,0.18); }
.fp-check { font-family: inherit; font-weight: 700; font-size: 14px; padding: 9px 16px; border-radius: 8px; border: none; background: var(--gold); color: white; cursor: pointer; }
.fp-check:hover { background: var(--copper); }
.fp-preview { font-size: 13px; color: var(--text-medium); }
.fp-preview .pv { display: inline-block; font-family: 'Inter', sans-serif; font-size: 18px; font-weight: 700; color: var(--brown-dark); vertical-align: middle; margin-left: 6px; min-width: 40px; }
.fp-preview .frac { display: inline-flex; flex-direction: column; align-items: center; vertical-align: middle; line-height: 1.05; }
.fp-preview .frac span:first-child { border-bottom: 2px solid var(--brown-dark); padding: 0 3px; }
.fp-preview .frac span:last-child { padding: 0 3px; }
.fp-fb { margin-top: 8px; font-size: 14px; min-height: 20px; }
.fp-fb.ok { color: var(--green-dark); font-weight: 600; }
.fp-fb.bad { color: #B23A3A; }
.fp-fb.bad strong { color: #B23A3A; }
.g-spr .fp-input { width: 170px; }
.g-spr .fp-preview .pv { min-width: 30px; }
#tab-fillin .card { margin-bottom: 20px; }
#tab-fillin .card p { margin-bottom: 10px; line-height: 1.7; }
#tab-fillin .section-header { margin-top: 30px; }
#tab-fillin .section-header:first-child { margin-top: 0; }

