/* ══════════ Formatting sprint ══════════ */
var FS = [["2/3", ".67", false, "Long decimals", "Two thirds does not fit, so you have to fill every space: .6666 or .6667 (0.666 and 0.667 also work). .67 is cut short."], ["2/3", ".6667", true, "Long decimals", "Fills all five spaces, rounded at the last digit. Accepted."], ["2/3", "2/3", true, "Fraction or decimal", "The fraction itself is always fine."], ["1/2", "0.5", true, "Fraction or decimal", "1/2, .5 and 0.5 all count."], ["3&frac12;", "31/2", false, "Mixed numbers", "Bluebook reads 31/2 as thirty-one halves. Type 7/2 or 3.5."], ["3&frac12;", "3.5", true, "Mixed numbers", "Convert the mixed number first. 3.5 or 7/2 both work."], ["25%", "25%", false, "No symbols", "No percent signs. If the answer is 25 percent, type 25."], ["25%", "25", true, "No symbols", "Just the number."], ["$1,200", "1,200", false, "No symbols", "No commas and no dollar signs. Type 1200."], ["$1,200", "1200", true, "No symbols", "Digits only."], ["&minus;4.5", "-4.5", true, "Negatives", "Minus sign first, then the number. Accepted."], ["&minus;4.5", "4.5-", false, "Negatives", "The minus sign has to come first."], ["&minus;1/3", "-.3333", true, "Negatives", "A negative answer gets six spaces (the minus sign counts), and -.3333 fills them."], ["&minus;1/3", "-.33", false, "Long decimals", "Too short. College Board rejects -.33 and -0.33. Fill the space: -.3333, -.3334, -0.333 or -0.334."], ["any value from 3 to 7", "5", true, "More than one answer", "Any one value in the range earns the point."], ["any value from 3 to 7", "3 to 7", false, "More than one answer", "Enter just one number. Never a range or a list."], ["0.5 or 1/2", "0.5 or 1/2", false, "More than one answer", "Pick one. Typing both is marked wrong."], ["5/9", ".5556", true, "Long decimals", "Fills the space, rounded at the last digit. Accepted."], ["6/8", "6/8", true, "Fraction or decimal", "You do not have to reduce. 6/8, 3/4 and .75 all count."], ["1.5", "3/2", true, "Fraction or decimal", "A fraction with the same value is fine."], ["7/2", "3 1/2", false, "Mixed numbers", "No spaces and no mixed numbers. Type 7/2 or 3.5."], ["&minus;3/4", "-0.75", true, "Negatives", "Minus first, five characters total. Accepted."], ["12.5", "12.50", true, "Fraction or decimal", "Same value, still five characters. Accepted."], ["1/8", ".125", true, "Fraction or decimal", "Terminates within the space, so the exact decimal works."]];
var fs = { order: [], i: 0, right: 0, t0: 0, times: [] };
function fsShuffle(a) { a = a.slice(); for (var i = a.length - 1; i > 0; i--) { var j = Math.floor(Math.random() * (i + 1)); var t = a[i]; a[i] = a[j]; a[j] = t; } return a; }
function fsStart() { fs.order = fsShuffle(FS.map(function(_, i) { return i; })); fs.i = 0; fs.right = 0; fs.times = []; fsShow(); }
function fsHud() {
  var avg = fs.times.length ? (fs.times.reduce(function(a, b) { return a + b; }, 0) / fs.times.length / 1000).toFixed(1) : '0.0';
  document.getElementById('fsHud').innerHTML = '<span>Item <b>' + Math.min(fs.i + 1, fs.order.length) + '</b> of ' + fs.order.length + '</span><span>Right: <b>' + fs.right + '</b></span><span>Avg: <b>' + avg + 's</b></span>';
}
function fsShow() {
  var item = document.getElementById('fsItem'), act = document.getElementById('fsActions'), v = document.getElementById('fsVerdict');
  v.className = 'sp-verdict'; v.innerHTML = '';
  if (fs.i >= fs.order.length) {
    var avg = (fs.times.reduce(function(a, b) { return a + b; }, 0) / fs.times.length / 1000).toFixed(1);
    item.innerHTML = '<div class="sp-done" style="grid-column:1/-1;">Sprint finished<small>' + fs.right + ' of ' + fs.order.length + ' right &middot; ' + avg + ' seconds per item' + (avg <= 3 ? '. That is test speed.' : '. Aim for under three.') + '</small></div>';
    act.innerHTML = '<button onclick="fsStart()">Run it again</button>'; fsHud(); return;
  }
  var d = FS[fs.order[fs.i]];
  item.innerHTML = '<div class="fs-box"><div class="fs-lab">Correct answer</div><div class="fs-val">' + d[0] + '</div></div>' +
                   '<div class="fs-box typed"><div class="fs-lab">Student typed</div><div class="fs-val">' + d[1] + '</div></div>';
  act.innerHTML = '<button onclick="fsAnswer(true)">&#10003; Accepted <span style="opacity:.6;font-weight:400;">(A)</span></button><button class="no" onclick="fsAnswer(false)">&#10007; Not accepted <span style="opacity:.6;font-weight:400;">(N)</span></button>';
  fs.t0 = Date.now(); fsHud();
}
function fsAnswer(yes) {
  if (fs.i >= fs.order.length) return;
  var d = FS[fs.order[fs.i]], ok = (yes === d[2]); fs.times.push(Date.now() - fs.t0); if (ok) fs.right++;
  var v = document.getElementById('fsVerdict'); v.className = 'sp-verdict ' + (ok ? 'ok' : 'bad');
  v.innerHTML = (ok ? 'Correct: ' : 'Not quite: ') + (d[2] ? 'accepted. ' : 'not accepted. ') + '<span class="rule">' + d[3] + '</span><span class="why">' + d[4] + '</span>';
  document.getElementById('fsActions').innerHTML = '<button onclick="fsNext()">Next &rarr;</button>';
  fs.i++; fsHud();
}
function fsNext() { fsShow(); }
document.addEventListener('keydown', function(e) {
  var tab = document.getElementById('tab-fillin'); if (!tab || !tab.classList.contains('active')) return;
  if (document.activeElement && document.activeElement.tagName === 'INPUT') return;
  var k = e.key.toLowerCase();
  var actions = document.getElementById('fsActions');
  if (actions && actions.textContent.indexOf('Next') >= 0) { if (k === 'enter' || k === ' ' || k === 'a' || k === 'n') { e.preventDefault(); fsNext(); } return; }
  if (k === 'a') fsAnswer(true); else if (k === 'n') fsAnswer(false);
});

/* ══════════ Type-it-in practice: College Board SPR rules ══════════ */
var FP = [["The solution is <strong>three and one quarter</strong>.", {"p": 13, "q": 4}, "mixed"], ["The answer is <strong>45 percent</strong>.", {"p": 45, "q": 1}, "symbol"], ["The answer is <strong>negative one half</strong>.", {"p": -1, "q": 2}, "neg"], ["The answer is <strong>two thirds</strong>.", {"p": 2, "q": 3}, "long"], ["The total cost is <strong>$1,250</strong>.", {"p": 1250, "q": 1}, "symbol"], ["<strong>Any value of x from 2 to 5</strong>, inclusive, is correct.", {"lo": 2, "hi": 5}, "range"], ["The answer is <strong>negative five ninths</strong>.", {"p": -5, "q": 9}, "long"], ["The area is <strong>12.5</strong> square units.", {"p": 25, "q": 2}, "plain"], ["The answer is <strong>seven halves</strong>.", {"p": 7, "q": 2}, "mixed"], ["The answer is <strong>one eighth</strong>.", {"p": 1, "q": 8}, "plain"]];
function fpGcd(a, b) { a = Math.abs(a); b = Math.abs(b); while (b) { var t = b; b = a % b; a = t; } return a; }
function fpDecimalString(p, q) {
  // shortest exact decimal of p/q, or null if it does not terminate
  var neg = p < 0; p = Math.abs(p); var g = fpGcd(p, q); p /= g; q /= g;
  var qq = q; while (qq % 2 === 0) qq /= 2; while (qq % 5 === 0) qq /= 5;
  if (qq !== 1) return null;
  var s = (p / q).toString(); if (s.indexOf('e') >= 0) return null;
  return (neg ? '-' : '') + s;
}
function fpPreview(e) {
  if (!e) return '<span class="pv" style="color:#999;font-weight:400;">&nbsp;</span>';
  var m = e.match(/^(-?)(\d*)\/(\d*)$/);
  if (m) return '<span class="pv">' + m[1] + '<span class="frac"><span>' + (m[2] || '&nbsp;') + '</span><span>' + (m[3] || '&nbsp;') + '</span></span></span>';
  return '<span class="pv">' + e.replace(/</g, '&lt;') + '</span>';
}
function fpCheck(entry, t, trap) {
  var e = entry.trim();
  if (!e) return [false, 'Type something first.'];
  if (/[%$]/.test(e)) return [false, 'No percent or dollar signs. Enter just the number.'];
  if (/,/.test(e)) return [false, 'No commas. Enter the digits only.'];
  if (/\s/.test(e)) return [false, 'No spaces. Bluebook stops at the first one.'];
  if (/[a-zA-Z]/.test(e) || /\b(or|to)\b/i.test(e)) return [false, 'Only digits, a decimal point, a fraction bar, and a leading minus sign are allowed.'];
  if (e.indexOf('-') > 0) return [false, 'The minus sign has to come first.'];
  if (!/^-?(\d+\.?\d*|\.\d+|\d+\/\d+)$/.test(e)) return [false, 'That is not a valid entry: digits, one decimal point or one fraction bar, and a minus sign first if needed.'];
  var neg = e.charAt(0) === '-', limit = neg ? 6 : 5;
  if (e.length > limit) return [false, 'Too long: ' + limit + ' characters is the limit' + (neg ? ' for a negative answer (the minus sign counts).' : '.')];
  var val, isFrac = e.indexOf('/') >= 0, a, b;
  if (isFrac) { var parts = e.replace('-', '').split('/'); a = parseInt(parts[0], 10); b = parseInt(parts[1], 10); if (b === 0) return [false, 'You cannot divide by zero.']; val = (neg ? -1 : 1) * a / b; }
  else val = parseFloat(e);
  if (t.lo !== undefined) {
    if (val >= t.lo && val <= t.hi) return [true, 'Any single value from ' + t.lo + ' to ' + t.hi + ' earns the point, and ' + e + ' is one of them.'];
    return [false, 'That equals ' + val + ', which is outside ' + t.lo + ' to ' + t.hi + '. Enter one value inside the range.'];
  }
  var p = t.p, q = t.q, target = p / q;
  if (isFrac) {
    if ((neg ? -a : a) * q === p * b) return [true, 'Exactly right: ' + e + ' equals ' + p + '/' + q + (fpGcd(a, b) !== 1 ? '. You did not need to reduce it.' : '.')];
    if (trap === 'mixed' && !neg && a > b && Math.abs(val - target) > 1) return [false, 'Bluebook reads ' + e + ' as ' + a + ' over ' + b + ' (' + val + '), not a mixed number. Convert first: ' + p + '/' + q + ' or ' + (p / q) + '.'];
    return [false, 'That equals ' + val + ', but the answer is ' + p + '/' + q + ' (' + target + ').'];
  }
  var exact = fpDecimalString(p, q);
  if (exact !== null && exact.length <= limit) {
    if (Math.abs(val - target) < 1e-9) return [true, 'Correct. ' + e + ' is exactly ' + target + '.'];
    return [false, 'That equals ' + val + ', but the answer is ' + target + '.'];
  }
  // non-terminating (or too long): must fill the space, truncated or rounded
  var digits = (e.split('.')[1] || '').length;
  var scale = Math.pow(10, digits);
  var trunc = (neg ? -1 : 1) * Math.floor(Math.abs(target) * scale + 1e-9) / scale;
  var round = (neg ? -1 : 1) * Math.round(Math.abs(target) * scale) / scale;
  var fills = e.length === limit;
  var matches = Math.abs(val - trunc) < 1e-9 || Math.abs(val - round) < 1e-9;
  var ex = fpFillExamples(p, q);
  if (fills && matches) return [true, 'Correct. ' + p + '/' + q + ' does not fit, and ' + e + ' fills every space. ' + ex + ' all work.'];
  if (matches && !fills) return [false, 'Risky. ' + p + '/' + q + ' does not fit, and College Board lists only entries that fill every space as acceptable (for 2/3: .6666, .6667, 0.666, 0.667). A shorter entry like ' + e + ' is not on their list, so do not gamble on it. Fill every space: ' + ex + '.'];
  return [false, 'That equals ' + val + ', but the answer is ' + p + '/' + q + '. Enter the fraction, or fill every space: ' + ex + '.'];
}
function fpFillExamples(p, q) {
  var neg = p < 0, v = Math.abs(p) / q, out = [];
  var d4 = neg ? 4 : 4, d3 = 3;
  var tr = Math.floor(v * 10000 + 1e-9) / 10000, ro = Math.round(v * 10000) / 10000;
  var s1 = tr.toFixed(4).replace(/^0/, ''), s2 = ro.toFixed(4).replace(/^0/, '');
  out.push((neg ? '-' : '') + s1); if (s2 !== s1) out.push((neg ? '-' : '') + s2);
  var t3 = Math.floor(v * 1000 + 1e-9) / 1000, r3 = Math.round(v * 1000) / 1000;
  out.push((neg ? '-' : '') + t3.toFixed(3)); if (r3 !== t3) out.push((neg ? '-' : '') + r3.toFixed(3));
  return out.join(', ');
}
function fpRender() {
  var list = document.getElementById('fpList'); if (!list) return;
  list.innerHTML = FP.map(function(it, i) {
    return '<div class="fp-item" id="fp' + i + '"><div class="fp-q"><span class="n">' + (i + 1) + '</span>' + it[0] + '</div>' +
      '<div class="fp-row"><input class="fp-input" id="fpi' + i + '" maxlength="12" autocomplete="off" spellcheck="false" oninput="fpLive(' + i + ')" onkeydown="if(event.key===\'Enter\'){fpGo(' + i + ');}">' +
      '<button class="fp-check" onclick="fpGo(' + i + ')">Check</button>' +
      '<span class="fp-preview">Answer preview: <span id="fpp' + i + '">' + fpPreview('') + '</span></span></div>' +
      '<div class="fp-fb" id="fpf' + i + '"></div></div>';
  }).join('');
}
function fpLive(i) { document.getElementById('fpp' + i).innerHTML = fpPreview(document.getElementById('fpi' + i).value); }
function fpGo(i) {
  var it = FP[i], e = document.getElementById('fpi' + i).value, r = fpCheck(e, it[1], it[2]);
  var fb = document.getElementById('fpf' + i); fb.className = 'fp-fb ' + (r[0] ? 'ok' : 'bad');
  fb.innerHTML = (r[0] ? '&#10003; ' : '<strong>&#10007; Not accepted.</strong> ') + r[1];
  document.getElementById('fp' + i).classList.toggle('done', r[0]);
}
document.addEventListener('DOMContentLoaded', function() { fpRender(); if (document.getElementById('fsStage')) fsStart(); });
